-- 58. delivery_order
ON CONFLICT DO NOTHING;

-- Reconcile historical sample orders with the domain's DEL-YYYY-NNNNNN contract.
-- Keeping this repair keyed by the stable fixture IDs makes repeated local starts idempotent.
UPDATE delivery_order
SET delivery_number = 'DEL-2026-' || LPAD(RIGHT(id::text, 6), 6, '0')
WHERE id BETWEEN 'a0000000-0000-0000-0000-000000000001'::uuid
             AND 'a0000000-0000-0000-0000-000000000010'::uuid
  AND delivery_number !~ '^DEL-[0-9]{4}-[0-9]{6}$';

